package br.com.confirmacao.patient.infrastructure;import br.com.confirmacao.patient.domain.Patient;import org.springframework.data.domain.*;import org.springframework.data.jpa.repository.*;import java.util.*;public interface PatientRepository extends JpaRepository<Patient,UUID>{@Override@EntityGraph(attributePaths="professional")Page<Patient> findAll(Pageable p);@Override@EntityGraph(attributePaths="professional")Optional<Patient> findById(UUID id);@EntityGraph(attributePaths="professional")Page<Patient> findAllByProfessionalId(UUID id,Pageable p);@EntityGraph(attributePaths="professional")Optional<Patient> findByIdAndProfessionalId(UUID id,UUID professionalId);boolean existsByProfessionalIdAndPhone(UUID id,String phone);boolean existsByProfessionalIdAndPhoneAndIdNot(UUID id,String phone,UUID patientId);}
